import datetime
import uuid
from sqlalchemy import (
    Column,
    Integer,
    BigInteger,
    String,
    Float,
    Boolean,
    Text,
    DateTime,
    ForeignKey,
    JSON,
    Index,
)
from sqlalchemy.orm import relationship
from Backend.app.core.database import Base


def _gen_uuid() -> str:
    return str(uuid.uuid4())


CLINICAL_DISCLAIMER_TEXT = (
    "DECISION-SUPPORT ONLY: This output is generated by an AI research and clinical "
    "decision-support system. It is not a confirmed medical diagnosis and must be "
    "reviewed and verified by a qualified healthcare professional."
)


class Dataset(Base):
    """
    Registered fetal ultrasound dataset imported from Backblaze B2 or local authorized storage.
    """
    __tablename__ = "datasets"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    name = Column(String(150), unique=True, index=True, nullable=False)
    version = Column(String(50), nullable=False, default="1.0.0")
    description = Column(Text, nullable=True)
    license_info = Column(String(255), nullable=True)
    source_url = Column(String(512), nullable=True)

    b2_bucket = Column(String(150), nullable=True)
    b2_prefix = Column(String(512), nullable=True)

    status = Column(String(50), default="registered", index=True)  # registered, ingesting, ready, failed
    total_files = Column(Integer, default=0)
    supported_tasks = Column(JSON, nullable=True)  # e.g. ["fetal_head_segmentation", "hc_biometry"]
    split_summary = Column(JSON, nullable=True)  # {"train": N, "val": M, "test": K}
    inventory_report = Column(JSON, nullable=True)
    error_message = Column(Text, nullable=True)

    created_at = Column(DateTime, default=datetime.datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.datetime.utcnow, onupdate=datetime.datetime.utcnow)

    files = relationship("DatasetFile", back_populates="dataset", cascade="all, delete-orphan")
    examinations = relationship("Examination", back_populates="dataset")
    annotations = relationship("Annotation", back_populates="dataset", cascade="all, delete-orphan")
    training_runs = relationship("TrainingRun", back_populates="dataset")


class Examination(Base):
    """
    A fetal ultrasound examination belonging to a pseudonymous subject/patient.
    """
    __tablename__ = "examinations"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    examination_code = Column(String(120), unique=True, index=True, nullable=False, default=_gen_uuid)

    patient_id = Column(Integer, ForeignKey("patients.id", ondelete="CASCADE"), nullable=False, index=True)
    dataset_id = Column(Integer, ForeignKey("datasets.id", ondelete="SET NULL"), nullable=True, index=True)

    gestational_age_weeks = Column(Float, nullable=True)
    acquisition_device = Column(String(150), nullable=True)
    acquisition_site = Column(String(150), nullable=True)
    pixel_spacing_mm = Column(Float, nullable=True)
    standard_plane = Column(String(100), nullable=True)  # e.g. trans_thalamic, trans_ventricular, femur, abdomen
    status = Column(String(50), default="registered")
    notes = Column(Text, nullable=True)
    exam_date = Column(DateTime, nullable=True)

    created_at = Column(DateTime, default=datetime.datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.datetime.utcnow, onupdate=datetime.datetime.utcnow)

    patient = relationship("Patient", back_populates="examinations")
    dataset = relationship("Dataset", back_populates="examinations")
    dataset_files = relationship("DatasetFile", back_populates="examination")
    videos = relationship("UltrasoundVideo", back_populates="examination", cascade="all, delete-orphan")
    frames = relationship("ExtractedFrame", back_populates="examination", cascade="all, delete-orphan")
    analysis_jobs = relationship("AnalysisJob", back_populates="examination")
    analysis_reports = relationship("AnalysisReport", back_populates="examination")


class DatasetFile(Base):
    """
    Individual file belonging to a Dataset (archive, image, video, mask, or metadata CSV/JSON).
    Stores metadata and checksums in PostgreSQL while keeping binary content in B2/controlled storage.
    """
    __tablename__ = "dataset_files"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    dataset_id = Column(Integer, ForeignKey("datasets.id", ondelete="CASCADE"), nullable=False, index=True)
    subject_id = Column(Integer, ForeignKey("patients.id", ondelete="SET NULL"), nullable=True, index=True)
    examination_id = Column(Integer, ForeignKey("examinations.id", ondelete="SET NULL"), nullable=True, index=True)

    b2_bucket = Column(String(150), nullable=True)
    b2_object_key = Column(String(512), nullable=True, index=True)
    relative_path = Column(String(512), nullable=True)
    original_filename = Column(String(255), nullable=False)
    media_type = Column(String(50), nullable=False, default="image")  # image, video, annotation, metadata, archive, unsupported
    mime_type = Column(String(100), nullable=True)
    file_size_bytes = Column(BigInteger, nullable=True)
    sha256_checksum = Column(String(64), nullable=True, index=True)
    etag = Column(String(128), nullable=True)

    width = Column(Integer, nullable=True)
    height = Column(Integer, nullable=True)
    pixel_spacing_mm = Column(Float, nullable=True)
    split_subset = Column(String(30), default="unassigned", index=True)  # train, val, test, unassigned

    is_corrupt = Column(Boolean, default=False)
    is_duplicate = Column(Boolean, default=False)
    has_annotation = Column(Boolean, default=False)
    status = Column(String(50), default="discovered", index=True)  # discovered, verified, ingested, corrupt, duplicate, unsupported
    error_message = Column(Text, nullable=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    dataset = relationship("Dataset", back_populates="files")
    subject = relationship("Patient", back_populates="dataset_files")
    examination = relationship("Examination", back_populates="dataset_files")
    annotations = relationship("Annotation", back_populates="dataset_file", cascade="all, delete-orphan")


class UltrasoundVideo(Base):
    """
    Metadata record for an ultrasound video stored in B2 or local upload storage.
    """
    __tablename__ = "ultrasound_videos"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    examination_id = Column(Integer, ForeignKey("examinations.id", ondelete="CASCADE"), nullable=True, index=True)
    dataset_file_id = Column(Integer, ForeignKey("dataset_files.id", ondelete="SET NULL"), nullable=True)
    scan_id = Column(Integer, ForeignKey("ultrasound_scans.id", ondelete="SET NULL"), nullable=True, index=True)

    b2_bucket = Column(String(150), nullable=True)
    b2_object_key = Column(String(512), nullable=True, index=True)
    local_file_path = Column(String(512), nullable=True)
    original_filename = Column(String(255), nullable=False)
    mime_type = Column(String(100), nullable=True)
    file_size_bytes = Column(BigInteger, nullable=True)
    sha256_checksum = Column(String(64), nullable=True, index=True)

    codec = Column(String(50), nullable=True)
    fps = Column(Float, nullable=True)
    duration_seconds = Column(Float, nullable=True)
    total_frames = Column(Integer, nullable=True)
    width = Column(Integer, nullable=True)
    height = Column(Integer, nullable=True)
    pixel_spacing_mm = Column(Float, nullable=True)

    upload_status = Column(String(50), default="uploaded")
    processing_status = Column(String(50), default="pending", index=True)
    error_message = Column(Text, nullable=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.datetime.utcnow, onupdate=datetime.datetime.utcnow)

    examination = relationship("Examination", back_populates="videos")
    extracted_frames = relationship("ExtractedFrame", back_populates="video", cascade="all, delete-orphan")
    analysis_jobs = relationship("AnalysisJob", back_populates="video")


class ExtractedFrame(Base):
    """
    Individual frame extracted from an UltrasoundVideo or registered from a static examination image.
    Preserves exact frame index and timestamp_ms to prevent treating correlated video frames as independent.
    """
    __tablename__ = "extracted_frames"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    video_id = Column(Integer, ForeignKey("ultrasound_videos.id", ondelete="CASCADE"), nullable=True, index=True)
    examination_id = Column(Integer, ForeignKey("examinations.id", ondelete="CASCADE"), nullable=True, index=True)
    dataset_file_id = Column(Integer, ForeignKey("dataset_files.id", ondelete="SET NULL"), nullable=True, index=True)

    frame_index = Column(Integer, nullable=False, default=0, index=True)
    timestamp_ms = Column(Float, nullable=False, default=0.0)
    width = Column(Integer, nullable=True)
    height = Column(Integer, nullable=True)
    pixel_spacing_mm = Column(Float, nullable=True)

    b2_object_key = Column(String(512), nullable=True)
    local_cache_path = Column(String(512), nullable=True)
    sha256_checksum = Column(String(64), nullable=True)

    quality_score = Column(Float, nullable=True)
    quality_warnings = Column(JSON, nullable=True)
    is_standard_plane = Column(Boolean, default=False)
    processing_status = Column(String(50), default="extracted")
    error_message = Column(Text, nullable=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    video = relationship("UltrasoundVideo", back_populates="extracted_frames")
    examination = relationship("Examination", back_populates="frames")
    annotations = relationship("Annotation", back_populates="frame", cascade="all, delete-orphan")
    measurements = relationship("Measurement", back_populates="frame")


class Annotation(Base):
    """
    Ground-truth or verified annotation linked to a DatasetFile or ExtractedFrame.
    Tracks annotation type, task, provenance, and calibration parameters.
    """
    __tablename__ = "annotations"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    dataset_id = Column(Integer, ForeignKey("datasets.id", ondelete="CASCADE"), nullable=True, index=True)
    dataset_file_id = Column(Integer, ForeignKey("dataset_files.id", ondelete="CASCADE"), nullable=True, index=True)
    frame_id = Column(Integer, ForeignKey("extracted_frames.id", ondelete="CASCADE"), nullable=True, index=True)

    annotation_type = Column(String(80), nullable=False, index=True)
    # e.g., segmentation_mask, ellipse_parameters, contour, bounding_box, plane_label, biometry_ground_truth
    task_name = Column(String(100), nullable=False, default="fetal_head_segmentation", index=True)
    provenance = Column(String(100), nullable=False, default="dataset_ground_truth")

    mask_b2_key = Column(String(512), nullable=True)
    mask_local_path = Column(String(512), nullable=True)
    label_value = Column(String(150), nullable=True)
    geometry_json = Column(JSON, nullable=True)  # e.g. ellipse center/axes/angle, contour points, or bbox
    measurements_json = Column(JSON, nullable=True)  # e.g. {"hc_mm": 182.4, "bpd_mm": 51.2}
    pixel_spacing_mm = Column(Float, nullable=True)
    is_verified = Column(Boolean, default=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    dataset = relationship("Dataset", back_populates="annotations")
    dataset_file = relationship("DatasetFile", back_populates="annotations")
    frame = relationship("ExtractedFrame", back_populates="annotations")


class TrainingRun(Base):
    """
    Reproducible model training and evaluation execution record.
    """
    __tablename__ = "training_runs"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    dataset_id = Column(Integer, ForeignKey("datasets.id", ondelete="SET NULL"), nullable=True, index=True)
    dataset_version = Column(String(50), nullable=False, default="1.0.0")

    task_name = Column(String(100), nullable=False, index=True)
    architecture = Column(String(100), nullable=False)
    random_seed = Column(Integer, nullable=False, default=42)

    hyperparameters = Column(JSON, nullable=True)
    preprocessing_config = Column(JSON, nullable=True)
    split_manifest = Column(JSON, nullable=True)  # Subject-level train/val/test split verification

    status = Column(String(50), default="queued", index=True)  # queued, running, completed, failed
    epochs_completed = Column(Integer, default=0)
    best_val_metric = Column(Float, nullable=True)
    training_history = Column(JSON, nullable=True)  # Loss curves and epoch metrics
    evaluation_metrics = Column(JSON, nullable=True)  # Held-out test metrics (Dice, IoU, MAE, RMSE, etc.)
    subgroup_metrics = Column(JSON, nullable=True)
    error_message = Column(Text, nullable=True)

    started_at = Column(DateTime, nullable=True)
    completed_at = Column(DateTime, nullable=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    dataset = relationship("Dataset", back_populates="training_runs")
    model_versions = relationship("ModelVersion", back_populates="training_run")


class ModelVersion(Base):
    """
    Versioned model artifact registered in PostgreSQL and backed by Backblaze B2.
    """
    __tablename__ = "model_versions"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    training_run_id = Column(Integer, ForeignKey("training_runs.id", ondelete="SET NULL"), nullable=True, index=True)

    model_name = Column(String(120), nullable=False, index=True)
    version_tag = Column(String(80), unique=True, index=True, nullable=False)
    task_name = Column(String(100), nullable=False, index=True)
    architecture = Column(String(100), nullable=False)
    dataset_version = Column(String(50), nullable=True)

    b2_bucket = Column(String(150), nullable=True)
    b2_artifact_key = Column(String(512), nullable=True)
    local_artifact_path = Column(String(512), nullable=True)
    artifact_sha256 = Column(String(64), nullable=True)
    artifact_size_bytes = Column(BigInteger, nullable=True)

    preprocessing_config = Column(JSON, nullable=True)
    evaluation_summary = Column(JSON, nullable=True)
    confidence_intervals = Column(JSON, nullable=True)
    limitations_notes = Column(Text, nullable=True)
    is_active = Column(Boolean, default=True, index=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    training_run = relationship("TrainingRun", back_populates="model_versions")
    analysis_jobs = relationship("AnalysisJob", back_populates="model_version")


class AnalysisJob(Base):
    """
    Asynchronous or background analysis job for an image or ultrasound video.
    Traceable to source file checksum, model version, and processing configuration.
    """
    __tablename__ = "analysis_jobs"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    examination_id = Column(Integer, ForeignKey("examinations.id", ondelete="SET NULL"), nullable=True, index=True)
    scan_id = Column(Integer, ForeignKey("ultrasound_scans.id", ondelete="SET NULL"), nullable=True, index=True)
    video_id = Column(Integer, ForeignKey("ultrasound_videos.id", ondelete="SET NULL"), nullable=True, index=True)
    model_version_id = Column(Integer, ForeignKey("model_versions.id", ondelete="SET NULL"), nullable=True, index=True)
    session_id = Column(Integer, ForeignKey("ai_analysis_sessions.id", ondelete="SET NULL"), nullable=True, index=True)

    job_type = Column(String(50), nullable=False, default="image_analysis", index=True)
    # image_analysis, video_analysis, dataset_ingestion, model_training
    status = Column(String(50), nullable=False, default="queued", index=True)
    # queued, processing, completed, failed
    progress_percent = Column(Float, nullable=False, default=0.0)

    source_filename = Column(String(255), nullable=True)
    source_sha256 = Column(String(64), nullable=True, index=True)
    pixel_spacing_mm = Column(Float, nullable=True)
    input_b2_key = Column(String(512), nullable=True)
    input_local_path = Column(String(512), nullable=True)
    output_b2_key = Column(String(512), nullable=True)
    output_local_path = Column(String(512), nullable=True)

    processing_config = Column(JSON, nullable=True)
    quality_warnings = Column(JSON, nullable=True)
    result_summary = Column(JSON, nullable=True)
    error_message = Column(Text, nullable=True)
    processing_time_ms = Column(Float, nullable=True)

    created_at = Column(DateTime, default=datetime.datetime.utcnow)
    started_at = Column(DateTime, nullable=True)
    completed_at = Column(DateTime, nullable=True)

    examination = relationship("Examination", back_populates="analysis_jobs")
    video = relationship("UltrasoundVideo", back_populates="analysis_jobs")
    model_version = relationship("ModelVersion", back_populates="analysis_jobs")
    measurements = relationship("Measurement", back_populates="analysis_job", cascade="all, delete-orphan")
    reports = relationship("AnalysisReport", back_populates="analysis_job", cascade="all, delete-orphan")


class Measurement(Base):
    """
    Reproducible biometric measurement traceable to an AnalysisJob, Frame, and ModelVersion.
    Distinguishes calibrated millimeter (mm) measurements from uncalibrated pixel (px) measurements.
    """
    __tablename__ = "measurements"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    analysis_job_id = Column(Integer, ForeignKey("analysis_jobs.id", ondelete="CASCADE"), nullable=True, index=True)
    session_id = Column(Integer, ForeignKey("ai_analysis_sessions.id", ondelete="CASCADE"), nullable=True, index=True)
    frame_id = Column(Integer, ForeignKey("extracted_frames.id", ondelete="SET NULL"), nullable=True, index=True)

    model_version_tag = Column(String(80), nullable=True)
    measurement_type = Column(String(50), nullable=False, index=True)  # BPD, HC, OFD, AC, FL
    value = Column(Float, nullable=False)
    unit = Column(String(16), nullable=False, default="mm")  # "mm" if calibrated, else "px"
    value_mm = Column(Float, nullable=True)
    value_px = Column(Float, nullable=False)
    pixel_spacing_mm = Column(Float, nullable=True)
    is_calibrated = Column(Boolean, nullable=False, default=False)

    confidence_score = Column(Float, nullable=True)
    uncertainty_mm = Column(Float, nullable=True)
    uncertainty_px = Column(Float, nullable=True)
    estimated_ga_weeks = Column(Float, nullable=True)
    growth_percentile = Column(Float, nullable=True)
    method = Column(String(100), default="contour_ellipse_fit")
    quality_warnings = Column(JSON, nullable=True)
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    analysis_job = relationship("AnalysisJob", back_populates="measurements")
    frame = relationship("ExtractedFrame", back_populates="measurements")


class AnalysisReport(Base):
    """
    Structured decision-support report linking source file, model version, measurements,
    visualizations, confidence scores, and quality warnings.
    """
    __tablename__ = "analysis_reports"

    id = Column(Integer, primary_key=True, index=True)
    uuid = Column(String(36), unique=True, index=True, nullable=False, default=_gen_uuid)
    analysis_job_id = Column(Integer, ForeignKey("analysis_jobs.id", ondelete="CASCADE"), nullable=False, index=True)
    examination_id = Column(Integer, ForeignKey("examinations.id", ondelete="SET NULL"), nullable=True, index=True)
    scan_id = Column(Integer, ForeignKey("ultrasound_scans.id", ondelete="SET NULL"), nullable=True, index=True)

    model_version_tag = Column(String(80), nullable=False)
    source_file_sha256 = Column(String(64), nullable=True)
    processing_config = Column(JSON, nullable=True)

    report_title = Column(String(255), default="Fetalytics AI Decision-Support Analysis Report")
    disclaimer = Column(Text, nullable=False, default=CLINICAL_DISCLAIMER_TEXT)
    overall_confidence = Column(Float, nullable=True)
    quality_score = Column(Float, nullable=True)
    quality_warnings = Column(JSON, nullable=True)
    measurements_summary = Column(JSON, nullable=True)

    annotated_media_b2_key = Column(String(512), nullable=True)
    annotated_media_path = Column(String(512), nullable=True)
    report_json = Column(JSON, nullable=True)
    status = Column(String(50), default="generated")
    created_at = Column(DateTime, default=datetime.datetime.utcnow)

    analysis_job = relationship("AnalysisJob", back_populates="reports")
    examination = relationship("Examination", back_populates="analysis_reports")


Index("ix_dataset_files_dataset_split", DatasetFile.dataset_id, DatasetFile.split_subset)
Index("ix_extracted_frames_video_frame", ExtractedFrame.video_id, ExtractedFrame.frame_index)
